import attr

def test_type_conflict():
    try:
        @attr.s
        class MyClass:
            x: int = attr.ib(type=str)
    except ValueError as e:
        print(f"Caught expected error: {e}")
        assert "Type annotation and type argument cannot both be present" in str(e)
        assert "'x'" in str(e)
    else:
        print("Error not raised")
        raise AssertionError("ValueError was not raised")

if __name__ == "__main__":
    test_type_conflict()
